namespace seed_b_backend.Api.Domain;

public class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
    public string Description { get; set; } = null!;
    public string SubcategoryId { get; set; } = null!;

    public Subcategory Subcategory { get; set; } = null!;
    public List<ProductProperty> ProductProperties { get; set; } = [];
    public List<Offer> Offers { get; set; } = [];
}

1	import { DecimalPipe } from '@angular/common';
2	import { Component, computed, inject, OnInit, signal } from '@angular/core';
3	
4	import { PagedResult, ProductListItem, ProductsApi } from '../../core/api/products.api';
5	import { CategoryNav, CategorySelection } from './category-nav/category-nav';
6	
7	@Component({
8	  selector: 'app-catalog',
9	  imports: [DecimalPipe, CategoryNav],
10	  templateUrl: './catalog.html',
11	  styleUrl: './catalog.scss',
12	})
13	export class Catalog implements OnInit {
14	  private readonly productsApi = inject(ProductsApi);
15	
16	  protected readonly page = signal(1);
17	  protected readonly result = signal<PagedResult<ProductListItem> | null>(null);
18	  protected readonly loading = signal(false);
19	  protected readonly error = signal(false);
20	  protected readonly selectedCategoryId = signal<string | undefined>(undefined);
21	  protected readonly selectedSubcategoryId = signal<string | undefined>(undefined);
22	  protected readonly sortBy = signal<'price' | 'name' | undefined>(undefined);
23	  protected readonly sortDir = signal<'asc' | 'desc' | undefined>(undefined);
24	  protected readonly q = signal<string | undefined>(undefined);
25	  protected readonly sortSelectValue = computed(() => {
26	    const sortBy = this.sortBy();
27	    const sortDir = this.sortDir();
28	    return sortBy && sortDir ? `${sortBy}-${sortDir}` : '';
29	  });
30	
31	  ngOnInit(): void {
32	    this.loadPage(1);
33	  }
34	
35	  protected goToPage(page: number): void {
36	    if (this.loading() || page < 1 || (this.result() && page > this.result()!.pageCount)) {
37	      return;
38	    }
39	    this.loadPage(page);
40	  }
41	
42	  protected onCategorySelectionChange(selection: CategorySelection): void {
43	    if (this.loading()) {
44	      return;
45	    }
46	    this.selectedCategoryId.set(selection.categoryId ?? undefined);
47	    this.selectedSubcategoryId.set(selection.subcategoryId ?? undefined);
48	    this.loadPage(1);
49	  }
50	
51	  protected onSortSelectionChange(value: string): void {
52	    if (this.loading()) {
53	      return;
54	    }
55	    switch (value) {
56	      case 'price-asc':
57	        this.sortBy.set('price');
58	        this.sortDir.set('asc');
59	        break;
60	      case 'price-desc':
61	        this.sortBy.set('price');
62	        this.sortDir.set('desc');
63	        break;
64	      case 'name-asc':
65	        this.sortBy.set('name');
66	        this.sortDir.set('asc');
67	        break;
68	      case 'name-desc':
69	        this.sortBy.set('name');
70	        this.sortDir.set('desc');
71	        break;
72	      default:
73	        this.sortBy.set(undefined);
74	        this.sortDir.set(undefined);
75	    }
76	    this.loadPage(1);
77	  }
