88	  private loadPage(page: number): void {
89	    this.loading.set(true);
90	    this.error.set(false);
91	    this.productsApi
92	      .getProducts(
93	        page,
94	        this.selectedCategoryId(),
95	        this.selectedSubcategoryId(),
96	        this.sortBy(),
97	        this.sortDir(),
98	        this.q(),
99	      )
100	      .subscribe({
101	        next: (result) => {
102	          this.page.set(result.page);
103	          this.result.set(result);
104	          this.loading.set(false);
105	        },
106	        error: () => {
