1	using Microsoft.EntityFrameworkCore;
2	using seed_b_backend.Api.Data;
3	using seed_b_backend.Api.Dtos;
4	
5	namespace seed_b_backend.Api.Application;
6	
7	public class ProductQueryService(AppDbContext db)
8	{
9	    private const int PageSize = 20;
10	
11	    public async Task<PagedResultDto<ProductListItemDto>> GetProductsAsync(
12	        int page = 1,
13	        string? categoryId = null,
14	        string? subcategoryId = null,
15	        string? sortBy = null,
16	        string? sortDir = null,
17	        string? q = null,
18	        CancellationToken cancellationToken = default)
19	    {
20	        if (page < 1)
21	        {
22	            page = 1;
23	        }
24	
25	        var query = db.Products.AsNoTracking().AsQueryable();
26	
27	        if (!string.IsNullOrWhiteSpace(subcategoryId))
28	        {
29	            query = query.Where(p => p.SubcategoryId == subcategoryId);
30	        }
31	        else if (!string.IsNullOrWhiteSpace(categoryId))
32	        {
33	            query = query.Where(p => p.Subcategory.CategoryId == categoryId);
34	        }
35	
36	        if (!string.IsNullOrWhiteSpace(q))
37	        {
38	            var term = q.Trim().ToLower();
39	            query = query.Where(p => p.Name.ToLower().Contains(term) || p.Description.ToLower().Contains(term));
40	        }
41	
42	        var descending = string.Equals(sortDir?.Trim(), "desc", StringComparison.OrdinalIgnoreCase);
43	        query = sortBy?.Trim().ToLowerInvariant() switch
44	        {
45	            "price" => descending
46	                ? query.OrderByDescending(p => p.Offers.Select(o => (decimal?)o.Price).Min()).ThenBy(p => p.Id)
47	                : query.OrderBy(p => p.Offers.Select(o => (decimal?)o.Price).Min()).ThenBy(p => p.Id),
48	            "name" => descending
49	                ? query.OrderByDescending(p => p.Name).ThenBy(p => p.Id)
50	                : query.OrderBy(p => p.Name).ThenBy(p => p.Id),
51	            _ => query.OrderBy(p => p.Id)
52	        };
53	
54	        var totalCount = await query.CountAsync(cancellationToken);
55	        var pageCount = totalCount == 0 ? 0 : (int)Math.Ceiling(totalCount / (double)PageSize);
56	
57	        if (pageCount > 0 && page > pageCount)
58	        {
59	            page = pageCount;
60	        }
61	
62	        var items = await query
63	            .Skip((page - 1) * PageSize)
64	            .Take(PageSize)
65	            .Select(p => new ProductListItemDto
66	            {
67	                Id = p.Id,
68	                Name = p.Name,
69	                LowestPrice = p.Offers.Select(o => (decimal?)o.Price).Min()
70	            })
71	            .ToListAsync(cancellationToken);
72	
73	        return new PagedResultDto<ProductListItemDto>
74	        {
75	            Items = items,
76	            TotalCount = totalCount,
77	            PageCount = pageCount,
78	            Page = page,
79	            PageSize = PageSize
80	        };
81	    }
82	}
